public class Main {
    public static void main(String[] args) {
        int n = 0b{nb};
        int k = {k};

        int part = (n >> k) & 0b111;

        System.out.println("取出来的三位：" + bits3(part));
        System.out.println("它是多少：" + part);
    }

    static String bits3(int v) {
        String s = Integer.toBinaryString(v & 0b111);
        while (s.length() < 3) {
            s = "0" + s;
        }
        return s;
    }
}
